    public struct NetworkConnectorConfiguration: AWSEncodableShape & AWSDecodableShape {
        /// Configuration for a VPC egress network connector. Specifies the subnets, security groups, and network protocol for routing outbound traffic through your VPC.
        public let vpcEgressConfiguration: NetworkConnectorVpcEgressConfiguration?

        @inlinable
        public init(vpcEgressConfiguration: NetworkConnectorVpcEgressConfiguration? = nil) {
            self.vpcEgressConfiguration = vpcEgressConfiguration
        }

        public func validate(name: String) throws {
            try self.vpcEgressConfiguration?.validate(name: "\(name).vpcEgressConfiguration")
        }

        private enum CodingKeys: String, CodingKey {
            case vpcEgressConfiguration = "VpcEgressConfiguration"
        }
    }
}

// MARK: - Errors

/// Error enum for LambdaCore
public struct LambdaCoreErrorType: AWSErrorType {
    enum Code: String {
        case invalidParameterValueException = "InvalidParameterValueException"
        case networkConnectorLimitExceededException = "NetworkConnectorLimitExceededException"
        case resourceConflictException = "ResourceConflictException"
        case resourceNotFoundException = "ResourceNotFoundException"
        case serviceException = "ServiceException"
        case tooManyRequestsException = "TooManyRequestsException"
    }

    private let error: Code
    public let context: AWSErrorContext?

    /// initialize LambdaCore
    public init?(errorCode: String, context: AWSErrorContext) {
        guard let error = Code(rawValue: errorCode) else { return nil }
        self.error = error
        self.context = context
    }

    internal init(_ error: Code) {
        self.error = error
        self.context = nil
    }

    /// return error code string
    public var errorCode: String { self.error.rawValue }

    /// One of the parameters in the request is not valid. Check the error message for details about which parameter failed validation.
    public static var invalidParameterValueException: Self { .init(.invalidParameterValueException) }
    /// The account has reached the maximum number of network connectors allowed. Delete unused connectors or request a limit increase through Service Quotas.
    public static var networkConnectorLimitExceededException: Self { .init(.networkConnectorLimitExceededException) }
    /// The request could not be completed due to a conflict with the current state of the resource. For example, attempting to update a connector that is not in ACTIVE state.
    public static var resourceConflictException: Self { .init(.resourceConflictException) }
    /// The specified network connector does not exist. Verify the identifier (ID, name, or ARN) and Region.
    public static var resourceNotFoundException: Self { .init(.resourceNotFoundException) }
    /// An internal service error occurred. Retry the request with exponential backoff.
    public static var serviceException: Self { .init(.serviceException) }
    /// The request was throttled due to exceeding the allowed request rate. Retry the request after a brief wait using exponential backoff.
    public static var tooManyRequestsException: Self { .init(.tooManyRequestsException) }
}

extension LambdaCoreErrorType: AWSServiceErrorType {
    public static let errorCodeMap: [String: AWSErrorShape.Type] = [
        "InvalidParameterValueException": LambdaCore.InvalidParameterValueException.self,
        "NetworkConnectorLimitExceededException": LambdaCore.NetworkConnectorLimitExceededException.self,
        "ResourceConflictException": LambdaCore.ResourceConflictException.self,
        "ResourceNotFoundException": LambdaCore.ResourceNotFoundException.self,
        "ServiceException": LambdaCore.ServiceException.self,
        "TooManyRequestsException": LambdaCore.TooManyRequestsException.self
    ]
}

extension LambdaCoreErrorType: Equatable {
    public static func == (lhs: LambdaCoreErrorType, rhs: LambdaCoreErrorType) -> Bool {
        lhs.error == rhs.error
    }
}

extension LambdaCoreErrorType: CustomStringConvertible {
    public var description: String {
        return "\(self.error.rawValue): \(self.message ?? "")"
    }
}
